def analyze_diagonal(n, function):
    # function(i, j) returns the value 0, 1, or 2 for cell (i, j)
    counts = {0: 0, 1: 0, 2: 0}

    # Main Diagonal: i = j
    main_diag_counts = {0: 0, 1: 0, 2: 0}
    for i in range(1, n + 1):
        val = function(i, i)
        main_diag_counts[val] += 1

    # Anti-Diagonal: i + j = n + 1
    anti_diag_counts = {0: 0, 1: 0, 2: 0}
    for i in range(1, n + 1):
        j = n + 1 - i
        val = function(i, j)
        anti_diag_counts[val] += 1

    return main_diag_counts, anti_diag_counts

# Arithmetic construction: A[i][j] = (i + j) mod 3
def arith_func(i, j):
    return (i + j) % 3

n = 39
main_counts, anti_counts = analyze_diagonal(n, arith_func)

print(f"N={n}")
print("Main Diagonal Counts (0, 1, 2):", main_counts)
print("Anti-Diagonal Counts (0, 1, 2):", anti_counts)

